//! Model-agnostic generative UI gallery system.
//!
//! This crate implements a model-agnostic inference loop that reads sealed plugin blobs,
//! accepts operator guidance via Antigravity chat UI, and generates json-render.dev specs
//! rendered by the existing DSL interpreter.
//!
//! # Architecture
//!
//! 1. **Context Assembler** — Gathers baseline context (blobs, docs, catalog)
//! 2. **Inference Loop** — Calls ZeroClaw `/v1/chat/completions` with tool support
//! 3. **Spec Validator** — Validates generated specs against grammar
//! 4. **Gallery Admission** — Admits validated specs to catalog store
//!
//! # Model Agnosticism
//!
//! No model-specific code. Any model exposed through ZeroClaw can be used. Model selection
//! is ZeroClaw's responsibility via the zeroclaw plugin's `selected_provider` and
//! `selected_model` fields.

pub mod context;
pub mod inference;
pub mod validator;
pub mod admission;
pub mod tools;

pub use context::{GenerationContext, SchemaPayload};
pub use inference::InferenceLoop;
pub use validator::SpecValidator;
pub use admission::GalleryAdmission;

/// Gallery generation configuration
#[derive(Debug, Clone, serde::Deserialize)]
pub struct GalleryGenConfig {
    /// Target number of specs to generate (default: 200)
    pub target_count: usize,

    /// Maximum stable-core elements to protect (default: 40)
    pub stable_core_max: usize,

    /// ZeroClaw HTTP endpoint (default: "http://localhost:8082")
    pub zeroclaw_endpoint: String,

    /// Enable MCP tool layer for cross-blob discovery
    pub enable_mcp: bool,

    /// Enable Qdrant semantic search
    pub enable_qdrant: bool,

    /// Maximum inference turns per spec (default: 10)
    pub max_turns: usize,
}

impl Default for GalleryGenConfig {
    fn default() -> Self {
        Self {
            target_count: 200,
            stable_core_max: 40,
            zeroclaw_endpoint: "http://localhost:8082".to_string(),
            enable_mcp: false,
            enable_qdrant: false,
            max_turns: 10,
        }
    }
}

//! Context assembler for gallery generation.
//!
//! Gathers baseline context for the inference loop:
//! - Plugin schemas from sealed blobs
//! - Static documentation (access-instructions, catalog, grammar)
//! - Operator guidance from Antigravity chat

use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// Assembled context for a single generation run.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GenerationContext {
    /// Baseline: all plugin schemas from blobs
    pub schemas: Vec<SchemaPayload>,

    /// Static docs: access-instructions.md content
    pub access_instructions: String,

    /// Static docs: json-render-catalog.md content  
    pub catalog_docs: String,

    /// Static docs: spec-grammar.md content
    pub grammar_docs: String,

    /// Universal prompt (vague, goal-oriented)
    pub universal_prompt: String,

    /// Operator guidance from Antigravity chat
    pub operator_guidance: Option<String>,

    /// MCP toggle enabled
    pub mcp_enabled: bool,

    /// Qdrant toggle enabled
    pub qdrant_enabled: bool,
}

/// Schema payload from a plugin blob.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SchemaPayload {
    /// Plugin name
    pub name: String,

    /// Plugin version
    pub version: String,

    /// Human-readable description
    pub description: Option<String>,

    /// OSCAL category (software, network, system, security, compliance, observability)
    pub category: Option<String>,

    /// State fields with types and constraints
    pub fields: HashMap<String, FieldSchema>,

    /// Available methods
    pub methods: HashMap<String, MethodSchema>,

    /// OSCAL subids for traceability
    pub subids: HashMap<String, String>,

    /// Raw schema JSON (for tool responses)
    pub raw_json: serde_json::Value,
}

/// Field schema from a plugin.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FieldSchema {
    /// Field type (string, number, boolean, object, array)
    pub field_type: FieldType,

    /// Human-readable description
    pub description: Option<String>,

    /// Default value if not specified
    pub default: Option<serde_json::Value>,

    /// Whether field is required
    pub required: bool,

    /// Whether field is read-only
    pub read_only: bool,

    /// Validation constraints
    pub constraints: Option<Constraints>,

    /// OSCAL subid
    pub subid: Option<String>,
}

/// Field type variants.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum FieldType {
    String,
    Number,
    Integer,
    Boolean,
    Array { items: Box<FieldType> },
    Object { properties: HashMap<String, FieldSchema> },
    Enum { values: Vec<String> },
    OneOf { variants: Vec<FieldType> },
}

/// Validation constraints for a field.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Constraints {
    pub min: Option<f64>,
    pub max: Option<f64>,
    pub pattern: Option<String>,
    pub min_length: Option<usize>,
    pub max_length: Option<usize>,
}

/// Method schema from a plugin.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MethodSchema {
    /// Human-readable description
    pub description: Option<String>,

    /// Input argument schema
    pub args: Option<serde_json::Value>,

    /// Return value schema
    pub returns: Option<serde_json::Value>,

    /// Side effect classification
    pub side_effect: SideEffect,

    /// Whether method is idempotent
    pub idempotent: bool,

    /// Required capability to invoke
    pub required_capability: Option<String>,

    /// OSCAL subid
    pub subid: Option<String>,
}

/// Method side effect classification.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SideEffect {
    Read,
    Mutation,
}

impl GenerationContext {
    /// Create a new generation context with baseline data.
    pub fn new(schemas: Vec<SchemaPayload>) -> Self {
        Self {
            schemas,
            access_instructions: include_str!("../../../docs/gallery-gen/access-instructions.md").to_string(),
            catalog_docs: include_str!("../../../docs/gallery-gen/json-render-catalog.md").to_string(),
            grammar_docs: include_str!("../../../docs/gallery-gen/spec-grammar.md").to_string(),
            universal_prompt: "Make this dataset as accessible to as many people, industries, causes as possible.".to_string(),
            operator_guidance: None,
            mcp_enabled: false,
            qdrant_enabled: false,
        }
    }

    /// Build the system message for the inference model.
    pub fn build_system_message(&self) -> String {
        let mut parts = vec![
            "# Gallery Generation System".to_string(),
            "".to_string(),
            "You are a UI specification generator. Your task is to create json-render.dev specifications that make plugin data accessible and useful.".to_string(),
            "".to_string(),
            "## Available Plugins".to_string(),
        ];

        for schema in &self.schemas {
            parts.push(format!("- **{}** ({}): {}", 
                schema.name, 
                schema.version,
                schema.description.as_deref().unwrap_or("No description")
            ));
        }

        parts.push("".to_string());
        parts.push("## Component Catalog".to_string());
        parts.push(self.catalog_docs.clone());
        parts.push("".to_string());
        parts.push("## Spec Grammar".to_string());
        parts.push(self.grammar_docs.clone());
        parts.push("".to_string());
        parts.push("## Plugin Schema Access".to_string());
        parts.push(self.access_instructions.clone());

        parts.join("\n")
    }

    /// Build the user message with universal prompt and operator guidance.
    pub fn build_user_message(&self) -> String {
        let mut msg = self.universal_prompt.clone();

        if let Some(guidance) = &self.operator_guidance {
            msg.push_str("\n\n## Operator Guidance\n");
            msg.push_str(guidance);
        }

        msg
    }
}

impl SchemaPayload {
    /// Parse a schema payload from raw plugin schema JSON.
    pub fn from_raw(name: String, raw: serde_json::Value) -> Result<Self> {
        let version = raw.get("version")
            .and_then(|v| v.as_str())
            .unwrap_or("1.0.0")
            .to_string();

        let description = raw.get("description")
            .and_then(|d| d.as_str())
            .map(|s| s.to_string());

        let category = raw.get("x-oscal-category")
            .and_then(|c| c.as_str())
            .map(|s| s.to_string());

        // Parse fields (simplified for now - full parsing would be recursive)
        let fields = parse_fields(raw.get("fields"))?;

        // Parse methods
        let methods = parse_methods(raw.get("methods"))?;

        // Extract subids
        let subids = raw.get("subids")
            .and_then(|s| s.as_object())
            .map(|obj| {
                obj.iter()
                    .map(|(k, v)| (k.clone(), v.as_str().unwrap_or("").to_string()))
                    .collect()
            })
            .unwrap_or_default();

        Ok(Self {
            name,
            version,
            description,
            category,
            fields,
            methods,
            subids,
            raw_json: raw,
        })
    }
}

fn parse_fields(fields_val: Option<&serde_json::Value>) -> Result<HashMap<String, FieldSchema>> {
    let mut fields = HashMap::new();

    if let Some(obj) = fields_val.and_then(|v| v.as_object()) {
        for (name, field_val) in obj {
            if let Ok(field) = parse_field(field_val) {
                fields.insert(name.clone(), field);
            }
        }
    }

    Ok(fields)
}

fn parse_field(val: &serde_json::Value) -> Result<FieldSchema> {
    let field_type = parse_field_type(val.get("field_type"))?;

    let description = val.get("description")
        .and_then(|d| d.as_str())
        .map(|s| s.to_string());

    let default = val.get("default").cloned();
    let required = val.get("required").and_then(|r| r.as_bool()).unwrap_or(false);
    let read_only = val.get("read_only").and_then(|r| r.as_bool()).unwrap_or(false);

    let constraints = val.get("constraints").map(|c| parse_constraints(c));

    let subid = val.get("subid")
        .and_then(|s| s.as_str())
        .map(|s| s.to_string());

    Ok(FieldSchema {
        field_type,
        description,
        default,
        required,
        read_only,
        constraints,
        subid,
    })
}

fn parse_field_type(val: Option<&serde_json::Value>) -> Result<FieldType> {
    match val {
        Some(serde_json::Value::String(s)) => {
            match s.as_str() {
                "string" => Ok(FieldType::String),
                "number" => Ok(FieldType::Number),
                "integer" => Ok(FieldType::Integer),
                "boolean" => Ok(FieldType::Boolean),
                _ => Ok(FieldType::String), // Default fallback
            }
        }
        Some(serde_json::Value::Object(obj)) => {
            if let Some(items) = obj.get("array") {
                let item_type = parse_field_type(Some(items))?;
                Ok(FieldType::Array { items: Box::new(item_type) })
            } else if let Some(props) = obj.get("object") {
                let properties = parse_fields(Some(props))?;
                Ok(FieldType::Object { properties })
            } else if let Some(vals) = obj.get("enumValues") {
                let values = vals.as_array()
                    .map(|arr| arr.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect())
                    .unwrap_or_default();
                Ok(FieldType::Enum { values })
            } else {
                Ok(FieldType::String)
            }
        }
        _ => Ok(FieldType::String),
    }
}

fn parse_constraints(val: &serde_json::Value) -> Constraints {
    Constraints {
        min: val.get("min").and_then(|v| v.as_f64()),
        max: val.get("max").and_then(|v| v.as_f64()),
        pattern: val.get("pattern").and_then(|v| v.as_str().map(|s| s.to_string())),
        min_length: val.get("minLength").and_then(|v| v.as_u64().map(|n| n as usize)),
        max_length: val.get("maxLength").and_then(|v| v.as_u64().map(|n| n as usize)),
    }
}

fn parse_methods(methods_val: Option<&serde_json::Value>) -> Result<HashMap<String, MethodSchema>> {
    let mut methods = HashMap::new();

    if let Some(obj) = methods_val.and_then(|v| v.as_object()) {
        for (name, method_val) in obj {
            if let Ok(method) = parse_method(method_val) {
                methods.insert(name.clone(), method);
            }
        }
    }

    Ok(methods)
}

fn parse_method(val: &serde_json::Value) -> Result<MethodSchema> {
    let description = val.get("description")
        .and_then(|d| d.as_str())
        .map(|s| s.to_string());

    let args = val.get("args").cloned();
    let returns = val.get("returns").cloned();

    let side_effect = val.get("side_effect")
        .and_then(|s| s.as_str())
        .map(|s| match s {
            "mutation" => SideEffect::Mutation,
            _ => SideEffect::Read,
        })
        .unwrap_or(SideEffect::Read);

    let idempotent = val.get("idempotent")
        .and_then(|i| i.as_bool())
        .unwrap_or(false);

    let required_capability = val.get("required_capability")
        .and_then(|c| c.as_str())
        .map(|s| s.to_string());

    let subid = val.get("subid")
        .and_then(|s| s.as_str())
        .map(|s| s.to_string());

    Ok(MethodSchema {
        description,
        args,
        returns,
        side_effect,
        idempotent,
        required_capability,
        subid,
    })
}

//! Inference loop for gallery generation.
//!
//! Calls ZeroClaw `/v1/chat/completions` with tool support for:
//! - Plugin schema queries
//! - MCP cross-blob discovery (when enabled)
//! - Qdrant semantic search (when enabled)

use anyhow::{Result, Context};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

use crate::context::GenerationContext;
use crate::tools::{ToolRegistry, ToolCall, ToolResult};

/// Inference loop that generates UI specs.
pub struct InferenceLoop {
    /// ZeroClaw HTTP client
    client: reqwest::Client,

    /// ZeroClaw endpoint
    endpoint: String,

    /// Maximum turns per spec
    max_turns: usize,

    /// Tool registry
    tools: ToolRegistry,
}

/// OpenAI-compatible chat message.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChatMessage {
    pub role: String,
    pub content: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_calls: Option<Vec<ToolCall>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tool_call_id: Option<String>,
}

/// OpenAI-compatible chat completion request.
#[derive(Debug, Clone, Serialize)]
pub struct ChatRequest {
    pub model: String,
    pub messages: Vec<ChatMessage>,
    pub tools: Option<Vec<ToolDefinition>>,
    pub stream: bool,
}

/// OpenAI-compatible tool definition.
#[derive(Debug, Clone, Serialize)]
pub struct ToolDefinition {
    #[serde(rename = "type")]
    pub tool_type: String,
    pub function: FunctionDefinition,
}

/// OpenAI-compatible function definition.
#[derive(Debug, Clone, Serialize)]
pub struct FunctionDefinition {
    pub name: String,
    pub description: String,
    pub parameters: serde_json::Value,
}

/// OpenAI-compatible chat completion response.
#[derive(Debug, Clone, Deserialize)]
pub struct ChatResponse {
    pub id: String,
    pub choices: Vec<Choice>,
}

/// Response choice.
#[derive(Debug, Clone, Deserialize)]
pub struct Choice {
    pub index: u32,
    pub message: ChatMessage,
    pub finish_reason: String,
}

/// Generated spec result.
#[derive(Debug, Clone)]
pub struct GeneratedSpec {
    /// The spec JSON
    pub spec: serde_json::Value,

    /// Plugin targeted
    pub target_plugin: Option<String>,

    /// Generation metadata
    pub metadata: HashMap<String, String>,
}

impl InferenceLoop {
    /// Create a new inference loop.
    pub fn new(endpoint: String, max_turns: usize) -> Self {
        Self {
            client: reqwest::Client::new(),
            endpoint,
            max_turns,
            tools: ToolRegistry::new(),
        }
    }

    /// Run a generation session.
    pub async fn generate(&self, ctx: &GenerationContext) -> Result<GeneratedSpec> {
        // Build initial messages
        let mut messages = vec![
            ChatMessage {
                role: "system".to_string(),
                content: Some(ctx.build_system_message()),
                tool_calls: None,
                tool_call_id: None,
            },
            ChatMessage {
                role: "user".to_string(),
                content: Some(ctx.build_user_message()),
                tool_calls: None,
                tool_call_id: None,
            },
        ];

        // Build tool definitions
        let tool_defs = self.build_tool_definitions(ctx);

        // Inference loop
        for turn in 0..self.max_turns {
            tracing::info!("Inference turn {} of {}", turn + 1, self.max_turns);

            // Call ZeroClaw
            let response = self.call_zeroclaw(&messages, &tool_defs).await
                .context("ZeroClaw inference call failed")?;

            // Extract assistant message
            let assistant_msg = response.choices.first()
                .map(|c| c.message.clone())
                .context("No response from model")?;

            // Check for tool calls
            if let Some(tool_calls) = &assistant_msg.tool_calls {
                // Add assistant message to history
                messages.push(assistant_msg.clone());

                // Execute tool calls
                for tool_call in tool_calls {
                    let result = self.tools.execute(tool_call, ctx).await;

                    // Add tool result to messages
                    messages.push(ChatMessage {
                        role: "tool".to_string(),
                        content: Some(serde_json::to_string(&result)?),
                        tool_calls: None,
                        tool_call_id: Some(tool_call.id.clone()),
                    });
                }
            } else {
                // No tool calls - check if we have a spec
                if let Some(content) = &assistant_msg.content {
                    if let Ok(spec) = self.extract_spec(content) {
                        tracing::info!("Successfully extracted spec on turn {}", turn + 1);
                        return Ok(GeneratedSpec {
                            spec,
                            target_plugin: None,
                            metadata: HashMap::new(),
                        });
                    }
                }

                // Add to history and continue
                messages.push(assistant_msg);
            }
        }

        anyhow::bail!("Max turns reached without generating a valid spec")
    }

    /// Call ZeroClaw chat completions endpoint.
    async fn call_zeroclaw(
        &self,
        messages: &[ChatMessage],
        tools: &[ToolDefinition],
    ) -> Result<ChatResponse> {
        let url = format!("{}/v1/chat/completions", self.endpoint);

        let request = ChatRequest {
            model: "default".to_string(), // ZeroClaw selects the actual model
            messages: messages.to_vec(),
            tools: if tools.is_empty() { None } else { Some(tools.to_vec()) },
            stream: false,
        };

        let response = self.client
            .post(&url)
            .json(&request)
            .send()
            .await
            .context("HTTP request failed")?;

        if !response.status().is_success() {
            let status = response.status();
            let body = response.text().await.unwrap_or_default();
            anyhow::bail!("ZeroClaw returned {}: {}", status, body);
        }

        response.json().await.context("Failed to parse response")
    }

    /// Build tool definitions based on enabled features.
    fn build_tool_definitions(&self, ctx: &GenerationContext) -> Vec<ToolDefinition> {
        let mut tools = vec![
            // Always available: list plugins
            ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "list_plugins".to_string(),
                    description: "List all available plugins with their names and categories".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {}
                    }),
                },
            },
            // Always available: get plugin schema
            ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "get_plugin_schema".to_string(),
                    description: "Get the full schema for a specific plugin".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "plugin_name": {
                                "type": "string",
                                "description": "Name of the plugin to get schema for"
                            }
                        },
                        "required": ["plugin_name"]
                    }),
                },
            },
            // Always available: search fields
            ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "search_fields".to_string(),
                    description: "Search for fields across all plugins by name pattern".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "pattern": {
                                "type": "string",
                                "description": "Pattern to search for in field names"
                            }
                        },
                        "required": ["pattern"]
                    }),
                },
            },
        ];

        // MCP-specific tools
        if ctx.mcp_enabled {
            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "search_methods".to_string(),
                    description: "Search for methods across all plugins by name pattern".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "pattern": {
                                "type": "string",
                                "description": "Pattern to search for in method names"
                            }
                        },
                        "required": ["pattern"]
                    }),
                },
            });

            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "search_subids".to_string(),
                    description: "Search for OSCAL subids by category or pattern".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "category": {
                                "type": "string",
                                "description": "OSCAL category to filter by (src, prj, sch, mut, obs, evt, exp)"
                            },
                            "pattern": {
                                "type": "string",
                                "description": "Pattern to search for in subids"
                            }
                        }
                    }),
                },
            });

            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "find_related".to_string(),
                    description: "Find plugins related to a given plugin by shared fields or methods".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "plugin_name": {
                                "type": "string",
                                "description": "Plugin to find relations for"
                            }
                        },
                        "required": ["plugin_name"]
                    }),
                },
            });
        }

        // Qdrant-specific tools
        if ctx.qdrant_enabled {
            tools.push(ToolDefinition {
                tool_type: "function".to_string(),
                function: FunctionDefinition {
                    name: "semantic_search".to_string(),
                    description: "Semantic search across all plugin schemas using vector embeddings".to_string(),
                    parameters: serde_json::json!({
                        "type": "object",
                        "properties": {
                            "query": {
                                "type": "string",
                                "description": "Natural language query to search for"
                            },
                            "limit": {
                                "type": "integer",
                                "description": "Maximum results to return",
                                "default": 10
                            }
                        },
                        "required": ["query"]
                    }),
                },
            });
        }

        tools
    }

    /// Extract a spec from model output.
    fn extract_spec(&self, content: &str) -> Result<serde_json::Value> {
        // Try to parse as direct JSON
        if let Ok(spec) = serde_json::from_str::<serde_json::Value>(content) {
            if spec.get("root").is_some() && spec.get("elements").is_some() {
                return Ok(spec);
            }
        }

        // Try to extract from markdown code block
        if let Some(json_start) = content.find("```json") {
            let json_start = json_start + 7;
            if let Some(json_end) = content[json_start..].find("```") {
                let json_str = &content[json_start..json_start + json_end].trim();
                if let Ok(spec) = serde_json::from_str::<serde_json::Value>(json_str) {
                    if spec.get("root").is_some() && spec.get("elements").is_some() {
                        return Ok(spec);
                    }
                }
            }
        }

        // Try to extract from generic code block
        if let Some(code_start) = content.find("```") {
            let code_start = code_start + 3;
            // Skip language identifier if present
            let code_start = if let Some(newline_pos) = content[code_start..].find('\n') {
                code_start + newline_pos + 1
            } else {
                code_start
            };

            if let Some(code_end) = content[code_start..].find("```") {
                let code_str = &content[code_start..code_start + code_end].trim();
                if let Ok(spec) = serde_json::from_str::<serde_json::Value>(code_str) {
                    if spec.get("root").is_some() && spec.get("elements").is_some() {
                        return Ok(spec);
                    }
                }
            }
        }

        anyhow::bail!("No valid spec found in model output")
    }
}

